"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["3721"],{66509(e){e.exports=JSON.parse('{"id":"FIN-1098","slug":"real-option","term":"Real Option","also_known_as":[],"difficulty":"Advanced","definition":"A real option is a right, but not an obligation, that a company has to make a future business decision, such as expanding, delaying, changing or abandoning an investment, as circumstances change.","explanation":["Traditional investment analysis, such as net present value, often assumes a company commits to a project and follows a fixed plan. In reality, managers can react to new information. Real options capture the value of this flexibility.","Common types include the option to expand if demand is strong, the option to abandon if results are poor, the option to delay investment until uncertainty clears, and the option to switch inputs or outputs, such as a power plant that can run on more than one fuel.","For example, a company building a factory may buy extra land, giving it the option to expand later if sales grow. The land has value beyond its immediate use because it keeps that choice open.","Real options can make a project worth more than its basic net present value suggests, especially when uncertainty is high. They can be valued with methods borrowed from financial option pricing, although estimating inputs such as volatility for real projects is difficult, so the analysis is often used to guide judgment rather than give precise values."],"note":"","total":1725,"prev":{"slug":"real-interest-rate","term":"Real Interest Rate"},"next":{"slug":"real-return","term":"Real Return"}}')}}]);